func pagerRangeValue(rows []pagerRange, codepoint rune, fallback int) int {
	low, high := 0, len(rows)
	for low < high {
		middle := low + (high-low)/2
		if rows[middle].last < codepoint {
			low = middle + 1
		} else {
			high = middle
		}
	}
	if low < len(rows) && rows[low].first <= codepoint {
		return rows[low].value
	}
	return fallback
}
